import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火地晉","description":"周易折中 - 火地晉","frontmatter":{"title":"火地晉","description":"周易折中 - 火地晉"},"headers":[],"relativePath":"classics/zhezhong/041.md","filePath":"classics/zhezhong/041.md"}'),h={name:"classics/zhezhong/041.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火地晉" tabindex="-1">火地晉 <a class="header-anchor" href="#火地晉" aria-label="Permalink to “火地晉”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈晉〉序卦：“物不可以終壯，故受之以晉。晉者，進也。物無壯而終止之理，既盛壯則必進，晉所以繼大壯也。為卦離在坤上，明出地上也。日出於地，升而益明，故為晉。晉進而光明盛大之意也。凡物漸盛為進，故《彖》雲：‘晉，進也。’卦有有徳者，有無徳者，隨其宜也。乾坤之外，雲元亨者固有也，雲利貞者，所不足而可以有功也。有不同者，革、漸是也。隨卦可見晉之盛，而無徳者無用有也。晉之明盛，故更不言亨，順乎大明，無用戒正也。”</p><p>晉 康侯用錫馬蕃庶，晝日三接</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>晉，進也。康侯，安國之侯也。錫馬蕃庶，晝日三接，言多受大賜而顯被親禮也。蓋其為卦上離下坤，有日出地上之象，順而麗乎大明之德。又其變自觀而來，為六四之柔進而上行以至於五，佔者有是三者，則亦當有是寵也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>晉為進盛之時，大明在上，而下體順附，諸侯承王之象也。故為康侯，康侯者，治安之侯也。上之大明而能司德以順附，治安之侯也。故受其𠖥數，錫之馬眾多也（車馬重賜也），蕃庶（眾多也）。不惟錫與之厚，又見親禮，晝日之中至於三接，言寵遇之至也。晉進盛之時，上明下順，君臣相得。在上而言，則進於明盛；在臣而言，則進升高顯，受其光寵也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>郭氏雍曰：晉卦取名之義與大有略相類。大有火在天上，君道也；晉明出地上，臣道也。以人臣之進獨備一卦之義，則臣之道至大者，非康侯安足以當之。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>《易》有晉、升、漸三卦，皆同為進義而有別。晉如日之方出，其義最優；升如木之方生，其義次之；漸如木之既生而以漸高大，其義又次之。觀其彖辭，皆可見矣。</p><p>象曰：明出地上，晉；君子以自昭明德</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>昭明之也</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>昭明之也。傳曰：“昭德塞違，昭其度也。”君子觀明出地上而益明盛之象，而以自昭其明德，去蔽致知。昭明德於己也，明明德於天下，昭明德於外也。明明德在己，故云“自昭”。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏炳文曰：至健莫如天，君子以之自強；至明莫如日，君子以之自昭。</p></li><li><p>俞氏琰曰：明德，君子固有之德也。自昭者，自有此德而自明之也。人德本明，人慾蔽之，不能不少昏昧，其本然之明固未嘗息。知所以自明，則本然之明如日之出地，而其昭著初無增減也。大學所謂“明明德”，所謂“自明”，與此同旨。</p></li></ul><p>彖曰：晉，進也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名義。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰 ：晉以日之進言，與升、漸木之進不同。日出地上，其明進而盛。升、漸雖亦有進義，而無明盛之象。</li></ul><p>明出地上，順而麗乎大明，柔進而上行，是以康侯用錫馬蕃庶，晝日三接也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦象、卦德、卦變釋卦辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>晉，進也，明進而盛也。明出於地，益進而盛，故為晉。所以不謂之進者，進謂前進，不能包明盛之義。明出地上，離在坤上也。坤麗於離，以順麗於大明，順德之臣上附於大明之君也。柔進而上行，凡卦離在上者，柔居君位，多雲柔進而上行（噬嗑、睽、鼎是也）。六五以柔居君位，明而順麗，為能待下寵遇親密之義，是以為康侯用錫馬蕃庶，晝日三接也。大明之君安天下者也，諸侯能順附天子之明德，是康民安國之侯也，故謂之康侯。是以享寵錫而見親禮，晝日之閒三接見於天子也。不曰公卿而曰侯，天子治於上者也，諸侯治於下者也。在下而順附於大明之君，諸侯之象也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>崔氏憬曰 ：雖一卦名晉，而五爻為主，故言柔進而上行也。</p></li><li><p>郭氏雍曰 ：順而麗乎大明，柔進而上行，康侯之德也。其德柔順而明，故下能康一國之民而為之主，上能致王者之寵而錫馬蕃庶，晝日三接也。</p></li><li><p>項氏安世曰 ：三女之卦，獨離柔在上為得尊位，大中而行之，故謂之上行。巽在六四例謂之上合，上同兌在上六例謂之上窮，皆不得為上行也。</p></li><li><p>王氏申子曰 ：六十四卦離上者八，專取六五一爻以為成卦之主者二，晉、大有也。大有曰“柔得尊位大中而上下應之”，晉則曰“柔進而上行”，是專以康侯之晉者當此一卦之義矣。</p></li><li><p>吳氏曰慎曰 ：晉、鹹《彖》傳文意正同，卦象數句在卦名之下，卦辭之上，是既用以釋卦名，而即以之釋卦辭，故用“是以”二字接下。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>離之德為麗、為明，是明與麗皆離也。順而麗乎大明，蓋以順德為本而為大明所附麗，則明者離而麗者亦離矣。若曰“以順而附麗於大明”，則麗字乃為坤所借用，其義不亦贅乎？火之為物不能孤行也，必有所附，猶人心之明不可孤行也，必有所附。離曰“畜牝牛”者，明附於順也。睽、旅之《彖》亦然，皆以說止為主而明附之也。此文義之誤，不可不正。</p><p>/books/106/35/1.html</p><p>初六 晉如摧如，貞吉，罔孚裕無咎</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>以陰居下，應不中正，欲進見摧之象。佔者如是而能守正則吉，設不為人所信，亦當處以寬裕，則無咎也。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>初居晉之下，進之始也。晉如，升進也；摧如，抑退也。於始進而言，遂其進不遂其進，惟得正則吉也。罔孚者，在下而始進，豈遽能深見信於上？苟上未見信，則當安中自守，雍容寬裕，無急於求上之信也。苟欲信之心切，非汲汲以失其守則，悻悻以傷於義矣，皆有咎也。故裕則無咎，君子處進退之道也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏安石曰：初六以柔進，君子也。度禮義以進退者也。常人不見孚，則或急於進以求有為，或急於退則懟上之不知。孔子曰：“我待價者也。”此罔孚而裕於進也。孟子乆於齊，此罔孚而裕於退也。</p></li><li><p>朱子語類：問：初六“晉如摧如”象也，“貞吉”佔辭。 曰：“罔孚裕無咎”，又是解上兩句，恐“貞吉”說不明，故又曉之。</p></li><li><p>問：初六“晉如摧如”象也，“貞吉”佔辭。 曰：“罔孚裕無咎”，又是解上兩句，恐“貞吉”說不明，故又曉之。</p></li><li><p>胡氏炳文曰：進之初，人多有未信者。然摧如在彼，而吾不可以不正；罔孚在人，而吾不可以不裕。貞與裕，皆戒辭也。</p></li></ul><p>象曰：晉如摧如，獨行正也；裕無咎，未受命也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>初居下位，未有官守之命</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>無進無抑，唯獨行正道也。寛裕則無咎者，始欲進而未當位故也。君子之於進退，或遲或速，唯義所當，未嘗不裕也。聖人恐後之人不達寛裕之義，居位者廢職失守以為裕，故特雲初六裕則無咎者，始進未受命，當職任故也。若有官守不信於上而失其職，一日不可居也。然事非一概，久速唯時，亦容有為之兆者。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏曰：君子之於正，不可以人之不見知而改其度。</p></li><li><p>張氏振淵曰：獨行正是原所以見摧之故。大凡君子處世，枉己易合，直道難容，惟正所以見摧，然安可因摧而自失其正？正與爻互相發明。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>未受命與臨九二同。臨、晉皆君子道長向用之卦也。然君子無急於乘勢趨時之意，當其臨也，至誠感物如忘其勢；當其進也，守道優遊若將終身。然故一則曰“未順命”，一則曰“未受命”。</p><p>六二：晉如愁如，貞吉。受茲介福，於其王母。</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>六二中正，上無應援，故欲進而愁。佔者如是而能守正則吉，而受福於王母也。王母指六五，蓋享先妣之吉占，而凡以陰居尊者皆其類也。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>六二在下，上無應援，以中正柔和之德，非強於進者也。故於進為可憂愁，謂其進之難也。然守其貞正則當得吉，故云“晉如愁如，貞吉”。王母，祖母也，謂陰之至尊者，指六五也。二以中正之道自守，雖上無應援不能自進，然其中正之德乆而必彰。上之人自當求之，蓋六五大明之君與之同德，必當求之，加以寵祿，受介福於王母也。介，大也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：小過六二曰“遇其妣”，彼言祖妣即此言王母也。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>二五相應者也，以陰應陽，以陽應陰，則有君臣之象；以陰應陰，則有妣婦之象。不曰母而曰王母者，禮重昭穆，故孫祔於祖，則孫婦祔於祖姑。蓋以昭穆相配，易爻以相配喻相應也。此明其為王母，而小過只言妣，蒙上過其祖之文爾。六五卦之主，而二應之，故有受福之義。</p><p>象曰：受茲介福，以中正也</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>受茲介福，以中正之道也。人能守中正之道，久而必亨，況大明在上而同德，必受大福也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏時曰：六二以柔順處乎眾陰而獨無應，是不見知也。故晉如愁如，然居中守正，素位而行，鬼神其福之矣。詩曰：“靖其爾位，好是正直，神之聽之，介爾景福。”此之謂也。</p></li><li><p>何氏楷曰：《爾雅》雲：“父之妣為王母。”小過六二遇妣，即此言王母。二五德同位應，二受介福，以其履中得正也。</p></li></ul><p>六三：眾允，悔亡。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>三不中正，宜有悔者。以其與下二陰皆欲上進，是以為眾所信，而悔亡也。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>以六居三，不得中正，宜有悔咎。而三在順體之上，順之極者也。三陰皆順上者，是三之順上與眾同志，眾所允從，其悔所以亡也。有順上嚮明之志，而眾允從之，何所不利？或曰：“不由中正而與眾同，得為善乎？”曰：“眾所允者，必至當也。況順上之大明，豈有不善？”是以悔亡，蓋亡其不中正之失矣。古人曰：“謀從眾，則合天心。”</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>吳氏曰 ：“愼曰：‘初罔孚，未信也；三眾允，見信也。’信於下，斯信於上，故弗信乎友，弗獲於上矣。”</li></ul><p>象曰：眾允之志，上行也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>上行上順，麗於大明也。上從大明之君，眾志之所同也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>李氏過曰：初之罔孚，眾未允也；二之愁如，猶有悔也；三德孚於眾，進得所願而悔亡也。</li></ul><p>九四：晉如鼫鼠，貞厲。</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>不中不正，以竊高位，貪而畏人，蓋危道也。故為鼫鼠之象，佔者如是，雖正亦危也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>以九居四，非其位也。非其位而居之，貪據其位者也。貪處高位，既非所安，而又與上同德，順麗於上。三陰皆在已下，勢必上進，故其心畏忌之。貪而畏人者，鼫鼠也。故云“晉如鼫鼠”，貪於非據而存畏忌之心。貞固守此，其危可知。言貞厲者，開有改之道也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰 ：“晉之道以順而麗乎大明，以柔進而上行，皆主乎順者也。三雖不正，以其能順，故得其志而上行。四雖已進乎上，以其失柔順之道，故如鼫鼠之窮而不得遂。”</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此卦以彖辭觀之，則九四以一陽而近君，康侯之位也。參之爻義，反不然者，蓋卦義所主在柔，則剛正與時義相反。當晉時，居高位而失靜正之道，乖退讓之節，貪而畏人，則非鼫鼠而何？貞厲者，戒其以持祿保位為常，而不知進退之義也。</p><p>象曰：鼫鼠貞厲，位不當也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>賢者以正德宜在高位，不正而處高位，則為非據。貪而懼失，則畏人，固處其地危可知也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>陸氏希聲曰：履非其位，固其寵祿。鼫鼠之志，竊食黍稷而已。</li></ul><p>六五：悔亡，失得勿恤，往吉，無不利。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以陰居陽，宜有悔矣。以大明在上，而下皆順從，故佔者得之，則其悔亡。又一切去其計功謀利之心，則往吉而無不利也。然亦必有其德，乃應其佔耳。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>六以柔居尊位，本當有悔。以大明在上而下皆順附，故其悔得亡也。下既同德順附，當推誠委任，盡眾人之才，通天下之志，勿復自任其明，恤其失得。如此而往，則吉而無不利也。六五大明之主，不患其不能明照，患其用明之過，至於察察，失委任之道。故戒以失得勿恤也。夫私意偏任不察，則有蔽；盡天下之公，豈當複用私察也？</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏牧曰 ：陽為躁動，陰為靜止。三五陽位，以陰居之，能節其動，故爻辭不稱晉而皆曰悔亡。</p></li><li><p>石氏介曰 ：以道自任，得之自是，失之自是，曾不以介意。小人患得患失，恤也。</p></li><li><p>胡氏炳文曰 ：事有不必憂者勿恤，寛之之辭也；有不當憂者勿恤，戒之之辭也。此曰“失得勿恤”，戒辭明矣。蓋當晉之時，易有患得患失之心。才柔又易有失得之累，大明在上，用其明於所當為，不當用其明於計功謀利之私也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>彖辭言康侯之被遇，而傳以柔進上行釋之，則聖人之意以此爻當康侯而為卦主明矣。蓋凡卦皆有主，其合於彖辭者是也。九四高位而爻辭不善，如此則彖辭之義誠非六五不足以當之。晉如鼫鼠者，患得患失，鄙夫之行也；失得勿恤者，竭誠盡忠，君子之志也。</p><p>象曰：失得勿恤，往有慶也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>以大明之德得下之附，推誠委任，則可以成天下之大功，是往而有福慶也。</p><p>上九：晉其角，維用伐邑，厲吉無咎，貞吝。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>角剛而居上，上九剛進之極，有其象矣。佔者得之，而以伐其私邑，則雖危而吉，且無咎。然以極剛治小邑，雖得其正，亦可吝矣。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>角剛而居上之物，上九以剛居卦之極，故取角為象。以陽居上，剛之極也，在晉之上，進之極也。剛極則有強猛之過，進極則有躁急之失。以剛而極於進，失中之甚也，無所用而可，維獨用於伐邑，則雖厲而吉，且無咎也。伐四方者，治外也；伐其居邑者，治內也。言伐邑，謂內自治也。人之自治，剛極則守道愈固，進極則遷善愈速。如上九者，以之自治，則雖傷於厲而吉，且無咎也。嚴厲非安和之道，而於自治則有功也。復雲貞吝，以盡其義，極於剛進，雖自治有功，然非中和之德，故以貞正之道為可吝也。不失中正為貞。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰 ：無可進而進，惟伐邑於內則可矣。如君子則知止也。</p></li><li><p>王氏宗傳曰 ：晉之上九，晉至於角，無所復進矣。惟能自反自克而內自治焉，則知危厲自警而𫉬吉矣。此所以無剛進之咎也。</p></li><li><p>朱子語類 （看伯豐與廬陵問答內晉卦伐邑說）曰：晉上九貞吝，吝不在克治，正以其克治之難而言其合下有此吝耳。貞吝之義，只雲貞固守此，則吝不應於此獨雲，於正道為吝也。</p></li><li><p>項氏安世曰 ：晉好柔而惡剛，故九四上九皆以厲言之。四進而非其道，故為鼫鼠；上已窮而猶晉，故為晉其角。</p></li><li><p>陸氏振奇曰 ：當晉之時，聖人最喜用柔而不用剛，故四陰吉悔亡，二陽厲且吝也。案：晉其角者，是知進而不知退者也。知進而不知退者，危道也。然亦有時事使然而進退甚難者，惟內治其私，反身無過，如居家則戒子弟戢僮僕，居官則杜交私嚴假託，皆伐邑之謂也。如此，則雖危而吉無咎矣。若以進為常，縱未至於危也，寧無愧於心乎？</p></li></ul><p>象曰：維用伐邑，道未光也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>維用伐邑，既得吉而無咎，復雲貞吝者，其道未光大也。以正理言之，尤可吝也。夫道既光大，則無不中正，安有過也？今以過剛自治，雖有功矣，然其道未光大，故亦可吝。聖人言盡善之道，案道未光乃推原所以伐邑之故。蓋進之極，則於道必未光也。如勢位重，則有居成功之嫌；爵祿羈，則失獨行願之志。故必克治其私，然後高而不危，免於亢悔也。夬五之“未光”同。</p><p>總論</p><ul><li><p>丘氏富國曰 ：晉進也，柔進而上行也。故卦專主柔進為義。六爻四柔二剛，六五一柔自四而升，已進者也，故往吉無不利。下坤三柔皆欲進者，而九四以剛間之，故有晉如鼫鼠之象。</p></li><li><p>趙氏汝騰曰 ：下三爻皆柔順而坤體，故初二吉三悔亡。四上以陽不當位，故厲且吝。惟五以柔明居尊位，故往吉無不利也。</p></li><li><p>龔氏煥曰 ：晉卦諸爻皆以進為義，初二三五柔之進，四與上剛之進也。四陰二陽，陰多吉而陽多厲者，晉以柔順為善，剛強則躁矣。故彖傳曰：“順而麗乎大明，柔進而上行。”卦之得名，其亦以柔為主與？</p></li></ul>',114)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
